function init(){setupTabs(),setupThemeToggle(),setupBookmark(),setupScrollAnimations(),setupJourneyIntegration()}function setupTabs(){const e=document.querySelectorAll(".tab-btn"),t=document.querySelectorAll(".tab-content");e.forEach(n=>{n.addEventListener("click",()=>{e.forEach(e=>e.classList.remove("active")),t.forEach(e=>e.classList.remove("active")),n.classList.add("active"),document.getElementById(n.dataset.tab).classList.add("active")})})}function setupThemeToggle(){const e=document.getElementById("theme-toggle");e.addEventListener("click",()=>{document.body.classList.toggle("light-theme"),localStorage.setItem("theme",document.body.classList.contains("light-theme")?"light":"dark"),e.textContent=document.body.classList.contains("light-theme")?"☀️":"🌙"}),"light"===localStorage.getItem("theme")&&(document.body.classList.add("light-theme"),e.textContent="☀️")}function setupBookmark(){const e=document.getElementById("bookmark-btn"),t="thrush-nilgiri-laughing";window.Journey&&window.Journey.isSaved(t)&&(e.textContent="✅ Saved to Journey"),e.addEventListener("click",()=>{window.Journey&&(window.Journey.toggle({id:t,explorerPage:"frontend/nilgiri-laughingthrush-explorer/index.html",title:"Nilgiri Laughingthrush",thumbnail:"https://placehold.co/100",category:"birds"}),e.textContent=window.Journey.isSaved(t)?"✅ Saved to Journey":"🔖 Bookmark to My Journey")})}let observer;function setupScrollAnimations(){observer=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&e.target.classList.add("visible")})},{threshold:.1}),document.querySelectorAll(".animate-on-scroll").forEach(e=>observer.observe(e))}function setupJourneyIntegration(){window.Journey&&window.Journey.registerSearchItems&&window.Journey.registerSearchItems("frontend/nilgiri-laughingthrush-explorer/index.html",[{id:"thrush-nilgiri-laughing",title:"Nilgiri Laughingthrush",description:"An endemic bird species of the Nilgiri Hills.",link:"#"}])}document.addEventListener("DOMContentLoaded",init);